-- Reviewed text-only exercise catalogue for the remote assistant.
-- This migration intentionally includes no third-party media.
insert into public.exercise_catalog (
  id, name, equipment, equipment_setup, technique_steps, coaching_cue, preparation, execution, breathing, common_mistakes, prescribed_sets, source_attribution, is_active
)
values
  ('sentadilla-barra', 'Sentadilla con barra', 'Barra y soportes', 'Una barra colocada a una altura que puedas retirar con control y espacio libre para moverte.', '[{"label":"Colócate","description":"Sitúa los pies a una anchura estable y apoya la barra sobre la parte alta de la espalda."},{"label":"Desciende","description":"Flexiona caderas y rodillas con el pecho alto, sin perder el control."},{"label":"Sube","description":"Empuja el suelo con todo el pie y vuelve de pie de forma continua."}]'::jsonb, 'Mantén las rodillas alineadas con los pies y usa una carga que controles.', 'Coloca los pies a una anchura cómoda, activa el tronco y retira la barra de los soportes solo si puedes hacerlo con estabilidad.', 'Desciende hasta una profundidad cómoda mientras mantienes el control; empuja el suelo para volver arriba sin rebotar.', 'Toma aire antes de descender y suéltalo de forma controlada al subir.', '["Perder el apoyo de todo el pie","Dejar que las rodillas caigan hacia dentro","Usar una carga que impide mantener el control"]'::jsonb, '[{"target":"3 × 6 repeticiones · RPE 6","rest":"120 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('press-banca-barra', 'Press de banca con barra', 'Banco, barra y soportes', 'Banco estable, barra con seguros si están disponibles y un peso que puedas controlar.', '[{"label":"Apóyate","description":"Apoya los pies, la espalda alta y la cabeza de forma estable sobre el banco."},{"label":"Baja","description":"Desciende la barra hacia el pecho de manera lenta y controlada."},{"label":"Empuja","description":"Extiende los brazos sin perder el apoyo de los pies ni acelerar al final."}]'::jsonb, 'Mantén los pies firmes y controla la barra durante todo el recorrido.', 'Túmbate con los pies apoyados y toma la barra con un agarre ligeramente más ancho que los hombros.', 'Baja la barra hacia el pecho con control y empuja hasta extender los brazos sin buscar velocidad innecesaria.', 'Inspira durante la bajada y expulsa el aire de forma gradual al empujar.', '["Perder el apoyo de los pies","Rebotar la barra sobre el pecho","Abrir los codos sin control"]'::jsonb, '[{"target":"3 × 8 repeticiones · RPE 7","rest":"90 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('jalon-pecho-polea', 'Jalón al pecho en polea', 'Polea alta y asiento con sujeción', 'Polea alta, barra de jalón y apoyo para fijar las piernas de forma cómoda.', '[{"label":"Fíjate","description":"Ajusta las piernas bajo las almohadillas y toma la barra con un agarre cómodo."},{"label":"Jala","description":"Lleva la barra hacia la parte alta del pecho acercando los omóplatos."},{"label":"Vuelve","description":"Deja subir la barra despacio sin encoger los hombros."}]'::jsonb, 'Lleva los codos hacia abajo sin tirar con impulso del tronco.', 'Siéntate estable, fija las piernas y mantén el pecho alto antes de iniciar el tirón.', 'Jala la barra hacia la parte superior del pecho con control y vuelve lento a los brazos extendidos.', 'Suelta el aire al jalar e inspira mientras la barra vuelve arriba.', '["Balancearse hacia atrás","Elevar los hombros","Soltar la carga demasiado rápido"]'::jsonb, '[{"target":"3 × 10 repeticiones · RPE 7","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('curl-biceps-mancuernas', 'Curl de bíceps con mancuernas', 'Mancuernas', 'Dos mancuernas que puedas levantar sin balancear el tronco.', '[{"label":"Prepárate","description":"Ponte de pie con los brazos junto al cuerpo y las palmas orientadas hacia delante."},{"label":"Flexiona","description":"Sube las mancuernas manteniendo los codos cerca de los costados."},{"label":"Baja","description":"Desciende lento hasta extender los brazos de nuevo."}]'::jsonb, 'Evita usar el impulso de la espalda para terminar cada repetición.', 'Colócate estable con una mancuerna en cada mano y los hombros relajados.', 'Flexiona los codos para elevar las mancuernas y baja de forma controlada sin balancearte.', 'Expulsa el aire al subir e inspira mientras bajas.', '["Balancear el tronco","Separar los codos del cuerpo","Bajar las mancuernas sin control"]'::jsonb, '[{"target":"2 × 12 repeticiones · RPE 7","rest":"60 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('extension-triceps-polea', 'Extensión de tríceps en polea', 'Polea alta y agarre en V', 'Polea en posición alta y un agarre que permita mantener las muñecas cómodas.', '[{"label":"Colócate","description":"Ponte frente a la polea con los codos cerca de los costados."},{"label":"Extiende","description":"Empuja el agarre hacia abajo sin mover los brazos superiores."},{"label":"Regresa","description":"Vuelve despacio al inicio conservando el control."}]'::jsonb, 'Mantén los codos estables y deja que el movimiento salga de la extensión del brazo.', 'Ajusta el agarre en la posición alta y adopta una postura estable frente a la máquina.', 'Extiende los brazos hacia abajo y vuelve lento sin usar el tronco para ayudar.', 'Suelta el aire al extender e inspira al regresar.', '["Mover los codos hacia delante","Inclinarse para usar el peso corporal","Soltar el agarre al volver"]'::jsonb, '[{"target":"2 × 12 repeticiones · RPE 7","rest":"60 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('zancada-mancuernas', 'Zancada con mancuernas', 'Mancuernas y espacio libre', 'Dos mancuernas ligeras o moderadas y un recorrido sin obstáculos.', '[{"label":"Da el paso","description":"Avanza con un pie manteniendo el tronco erguido."},{"label":"Desciende","description":"Baja con control hasta una profundidad cómoda para ambas rodillas."},{"label":"Vuelve","description":"Empuja el suelo con el pie adelantado para recuperar la posición inicial."}]'::jsonb, 'Usa un paso que te permita conservar equilibrio y una trayectoria cómoda de rodilla.', 'Ponte de pie con las mancuernas a los lados y espacio suficiente para avanzar.', 'Da un paso, desciende con control y empuja con el pie adelantado para volver; alterna lados.', 'Inspira al descender y suelta el aire al volver de pie.', '["Dar un paso demasiado corto","Perder el equilibrio por acelerar","Usar una carga que altera la técnica"]'::jsonb, '[{"target":"3 × 8 por lado · RPE 6","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('curl-martillo-mancuernas', 'Curl martillo con mancuernas', 'Mancuernas', 'Dos mancuernas que puedas mover sin balancear el tronco.', '[{"label":"Colócate","description":"Mantén las palmas mirando hacia el torso y los codos cerca del cuerpo."},{"label":"Flexiona","description":"Eleva las mancuernas con control sin mover los brazos superiores."},{"label":"Desciende","description":"Vuelve despacio a los brazos extendidos."}]'::jsonb, 'Mantén el tronco quieto: si necesitas impulso, reduce la carga.', 'Ponte de pie estable con una mancuerna en cada mano y agarre neutro.', 'Flexiona los codos para elevar las mancuernas y baja de forma controlada.', 'Suelta el aire al subir e inspira al bajar.', '["Balancear el tronco","Separar los codos del cuerpo","Acortar la bajada por usar demasiado peso"]'::jsonb, '[{"target":"2 × 12 repeticiones · RPE 7","rest":"60 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('extension-triceps-cuerda', 'Extensión de tríceps por encima de la cabeza', 'Polea alta y cuerda', 'Polea alta con cuerda y espacio suficiente para colocarte de espaldas a la máquina.', '[{"label":"Ajusta","description":"Colócate de espaldas a la polea con la cuerda sobre la cabeza."},{"label":"Flexiona","description":"Baja la cuerda detrás de la cabeza manteniendo los brazos superiores estables."},{"label":"Extiende","description":"Estira los brazos de forma controlada sin arquear la espalda."}]'::jsonb, 'Conserva los codos orientados hacia delante y un rango que controles.', 'Toma la cuerda con ambas manos y adopta una posición estable antes de elevar los brazos.', 'Flexiona y extiende los codos sobre la cabeza sin usar el impulso del tronco.', 'Inspira al flexionar y suelta el aire al extender.', '["Arquear la zona lumbar","Abrir los codos sin control","Usar una carga que obliga a acelerar"]'::jsonb, '[{"target":"2 × 12 repeticiones · RPE 7","rest":"60 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('plancha-rotacion', 'Plancha alta con rotación', 'Esterilla', 'Una esterilla o superficie estable que permita apoyar las manos con comodidad.', '[{"label":"Forma la plancha","description":"Coloca las manos bajo los hombros y crea una línea cómoda de cabeza a pies."},{"label":"Rota","description":"Gira el torso y eleva un brazo con control, sin acelerar."},{"label":"Alterna","description":"Vuelve al centro y cambia de lado manteniendo la pelvis estable."}]'::jsonb, 'Mueve con un rango que puedas controlar sin forzar la zona lumbar.', 'Empieza en plancha alta con manos bajo hombros y pies a una distancia estable.', 'Rota el torso hacia un lado, vuelve al centro y alterna con calma.', 'Respira de forma continua y evita contener el aire.', '["Dejar caer la pelvis","Girar con impulso","Forzar un rango incómodo"]'::jsonb, '[{"target":"2 × 8 por lado · RPE 6","rest":"45 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('sentadilla-peso-corporal', 'Sentadilla con peso corporal', 'Espacio libre', 'Una superficie firme, sin obstáculos y con espacio para mover los brazos.', '[{"label":"Colócate","description":"Apoya los pies a una anchura estable y reparte el peso en todo el pie."},{"label":"Desciende","description":"Lleva cadera y rodillas hacia abajo a un rango que controles."},{"label":"Sube","description":"Empuja el suelo para volver arriba sin rebotar."}]'::jsonb, 'Conserva el apoyo de todo el pie y una profundidad que te resulte cómoda.', 'Ponte de pie con los pies a una anchura cómoda y el tronco alto.', 'Desciende flexionando caderas y rodillas y vuelve de pie con control.', 'Toma aire antes de bajar y suéltalo de forma gradual al subir.', '["Levantar los talones","Dejar caer las rodillas hacia dentro","Bajar más de lo que puedes controlar"]'::jsonb, '[{"target":"3 × 10 repeticiones · RPE 6","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('zancada-peso-corporal', 'Zancada con peso corporal', 'Espacio libre', 'Una superficie firme y un recorrido libre de obstáculos.', '[{"label":"Da el paso","description":"Avanza con un paso que te permita mantener el equilibrio."},{"label":"Desciende","description":"Flexiona ambas piernas con el tronco erguido y controlado."},{"label":"Vuelve","description":"Empuja el suelo con el pie adelantado para regresar."}]'::jsonb, 'Haz el paso suficientemente amplio para que puedas mantener una trayectoria cómoda de rodilla.', 'Colócate de pie, estable y con espacio delante para avanzar.', 'Avanza, baja con control y vuelve al inicio; alterna lados.', 'Inspira al descender y expulsa el aire al volver de pie.', '["Acortar demasiado el paso","Perder el equilibrio por acelerar","Forzar una profundidad incómoda"]'::jsonb, '[{"target":"3 × 8 por lado · RPE 6","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('flexiones', 'Flexiones', 'Suelo o esterilla', 'Una superficie firme y despejada que no resbale.', '[{"label":"Forma la posición","description":"Coloca las manos bajo los hombros y crea una línea cómoda de cabeza a pies."},{"label":"Baja","description":"Flexiona los codos sin perder el control del tronco."},{"label":"Empuja","description":"Aleja el suelo para volver a la posición inicial."}]'::jsonb, 'Mantén el tronco estable; eleva las manos en una superficie firme si necesitas más margen.', 'Apoya manos y pies en el suelo con una distancia que te resulte estable.', 'Desciende el pecho hacia el suelo hasta un rango que controles y empuja para volver arriba.', 'Inspira al bajar y suelta el aire al empujar.', '["Dejar caer la pelvis","Abrir los codos sin control","Acortar el recorrido por acelerar"]'::jsonb, '[{"target":"3 × 6–10 repeticiones · RPE 6","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('sentadilla-banda', 'Sentadilla con banda', 'Banda de resistencia y espacio libre', 'Una banda en buen estado y una superficie firme; usa una tensión que puedas controlar.', '[{"label":"Coloca la banda","description":"Sitúala de forma estable bajo los pies y sujétala cerca de los hombros."},{"label":"Desciende","description":"Baja con control manteniendo el apoyo de todo el pie."},{"label":"Sube","description":"Empuja el suelo y deja que la banda acompañe el movimiento sin tirones."}]'::jsonb, 'Revisa la banda antes de empezar y no uses una tensión que altere tu postura.', 'Pisa el centro de la banda y adopta una posición estable antes de iniciar el descenso.', 'Haz una sentadilla con control y vuelve de pie sin acelerar al final.', 'Toma aire antes de descender y expúlsalo al subir.', '["Usar una banda dañada","Perder el apoyo de los talones","Buscar velocidad en la subida"]'::jsonb, '[{"target":"3 × 10 repeticiones · RPE 6","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('remo-banda-sentado', 'Remo sentado con banda', 'Banda de resistencia y esterilla', 'Una banda en buen estado, esterilla y un punto de apoyo con los pies estable.', '[{"label":"Siéntate","description":"Siéntate erguido con las piernas extendidas o ligeramente flexionadas."},{"label":"Rema","description":"Lleva la banda hacia el abdomen acercando los codos al cuerpo."},{"label":"Vuelve","description":"Extiende los brazos despacio sin encoger los hombros."}]'::jsonb, 'No redondees la espalda para buscar más recorrido; usa una tensión de banda que controles.', 'Pasa la banda por la planta de ambos pies y toma sus extremos con las manos.', 'Lleva los codos atrás mientras acercas las manos al abdomen y vuelve lento al inicio.', 'Suelta el aire al remar e inspira al extender los brazos.', '["Redondear la espalda","Tirar con impulso","Usar una banda deteriorada"]'::jsonb, '[{"target":"3 × 10–12 repeticiones · RPE 6","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('press-pecho-banda', 'Press de pecho con banda', 'Banda de resistencia y espacio libre', 'Una banda en buen estado colocada de forma estable detrás de la espalda, sin anclarla a mobiliario.', '[{"label":"Colócate","description":"Pasa la banda por la parte alta de la espalda y toma un extremo con cada mano."},{"label":"Empuja","description":"Extiende los brazos al frente sin perder el control del tronco."},{"label":"Vuelve","description":"Regresa despacio manteniendo los hombros relajados."}]'::jsonb, 'Inspecciona la banda antes de usarla y mantén una tensión que no altere la postura.', 'Adopta una zancada estable y coloca la banda detrás de la parte alta de la espalda.', 'Empuja las manos al frente y vuelve lento hacia el pecho, sin bloquear los codos con fuerza.', 'Expulsa el aire al empujar e inspira al volver.', '["Usar una banda dañada","Elevar los hombros","Arquear la espalda para terminar el empuje"]'::jsonb, '[{"target":"3 × 10–12 repeticiones · RPE 6","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('remo-mancuerna-banco', 'Remo con mancuerna y banco', 'Mancuerna y banco estable', 'Un banco firme y una mancuerna que puedas levantar sin girar el tronco.', '[{"label":"Apóyate","description":"Apoya una mano y la rodilla del mismo lado en el banco, con el otro pie firme en el suelo."},{"label":"Rema","description":"Lleva la mancuerna hacia la cadera acercando el codo al cuerpo."},{"label":"Vuelve","description":"Baja despacio hasta extender el brazo sin girar el tronco."}]'::jsonb, 'Mantén el tronco quieto; si necesitas girarlo para subir, reduce la carga.', 'Coloca el banco en una superficie firme y adopta un apoyo que te resulte estable.', 'Lleva la mancuerna hacia la cadera y vuelve de forma controlada; completa un lado antes de cambiar.', 'Suelta el aire al remar e inspira al bajar.', '["Girar el torso","Elevar el hombro hacia la oreja","Tirar con impulso"]'::jsonb, '[{"target":"3 × 8–10 por lado · RPE 7","rest":"75 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true),
  ('press-hombros-mancuernas', 'Press de hombros con mancuernas', 'Mancuernas y banco con respaldo opcional', 'Dos mancuernas que puedas controlar; si usas banco, debe estar firme y estable.', '[{"label":"Colócate","description":"Sujeta las mancuernas a la altura de los hombros con una postura estable."},{"label":"Empuja","description":"Eleva las mancuernas sin acelerar ni arquear la espalda."},{"label":"Baja","description":"Vuelve lento a la altura de los hombros."}]'::jsonb, 'Mantén las costillas y la pelvis estables; reduce carga si necesitas arquear la espalda.', 'Siéntate o ponte de pie con una base estable y las mancuernas cerca de los hombros.', 'Empuja las mancuernas por encima de la cabeza hasta un rango cómodo y vuelve controlado.', 'Expulsa el aire al empujar e inspira al bajar.', '["Arquear la espalda","Bajar demasiado rápido","Usar una carga que exige impulso"]'::jsonb, '[{"target":"3 × 8 repeticiones · RPE 7","rest":"90 s"}]'::jsonb, 'Adapted from hasaneyldrm/exercises-dataset (MIT); see docs/third-party-licenses.md.', true)
on conflict (id) do nothing;
